describe('Notification Preferences Management', () => {
  beforeEach(() => {
    cy.visit('/settings');
  });

  it('should successfully update notification preferences', () => {
    // Verify initial notification settings are displayed
    cy.get('[data-testid="notification-settings-section"]').should('be.visible');
    cy.get('[data-testid="email-notifications-checkbox"]').should('be.checked');
    cy.get('[data-testid="sms-notifications-checkbox"]').should('not.be.checked');
    cy.get('[data-testid="push-notifications-checkbox"]').should('not.be.checked');

    // Navigate to notification settings
    cy.get('[data-testid="notification-settings-toggle"]').click();

    // Verify settings are now expanded
    cy.get('[data-testid="notification-settings-section"]').should('be.visible');

    // Uncheck email notifications
    cy.get('[data-testid="email-notifications-checkbox"]').click();
    cy.get('[data-testid="email-notifications-checkbox"]').should('not.be.checked');

    // Verify SMS notifications are now checked
    cy.get('[data-testid="sms-notifications-checkbox"]').click();
    cy.get('[data-testid="sms-notifications-checkbox"]').should('be.checked');

    // Verify push notifications are still unchecked
    cy.get('[data-testid="push-notifications-checkbox"]').should('not.be.checked');

    // Save changes
    cy.get('[data-testid="save-preferences-button"]').click();

    // Verify success message appears
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Notification preferences updated');

    // Verify settings are still visible
    cy.get('[data-testid="notification-settings-section"]').should('be.visible');
  });

  it('should handle invalid input when updating notification preferences', () => {
    // Navigate to notification settings
    cy.get('[data-testid="notification-settings-toggle"]').click();

    // Attempt to uncheck all notifications
    cy.get('[data-testid="email-notifications-checkbox"]').click();
    cy.get('[data-testid="sms-notifications-checkbox"]').click();
    cy.get('[data-testid="push-notifications-checkbox"]').click();

    // Verify all notifications are now unchecked
    cy.get('[data-testid="email-notifications-checkbox"]').should('not.be.checked');
    cy.get('[data-testid="sms-notifications-checkbox"]').should('not.be.checked');
    cy.get('[data-testid="push-notifications-checkbox"]').should('not.be.checked');

    // Attempt to save with invalid state
    cy.get('[data-testid="save-preferences-button"]').click();

    // Verify error message appears
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Please select at least one notification type');

    // Verify settings are still visible
    cy.get('[data-testid="notification-settings-section"]').should('be.visible');
  });
});
